CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE OR REPLACE FUNCTION uuid_generate_v7()
RETURNS uuid
LANGUAGE plpgsql
AS $$
DECLARE
    ts bigint;
    hex text;
BEGIN
    ts := floor(extract(epoch from clock_timestamp()) * 1000);
    hex :=
        lpad(to_hex(ts),12,'0') ||
        encode(gen_random_bytes(10),'hex');
    RETURN (
        substr(hex,1,8) || '-' ||
        substr(hex,9,4) || '-' ||
        '7' || substr(hex,14,3) || '-' ||
        substr(hex,17,4) || '-' ||
        substr(hex,21,12)
    )::uuid;
END;
$$;

CREATE TABLE facility (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    name VARCHAR(100) UNIQUE NOT NULL,
    address VARCHAR(255) NOT NULL
);

CREATE TABLE staff_day_off (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    date_off DATE NOT NULL,
    staff_uuid UUID NOT NULL,
	facility_uuid UUID NOT NULL,
	reason TEXT,
	is_approved BOOLEAN NOT NULL DEFAULT FALSE	
);

CREATE TABLE shift (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    name VARCHAR(50) NOT NULL,
    checkin TIME NOT NULL,
    checkout TIME NOT NULL,
    duration NUMERIC(4,2)
);

CREATE TABLE staff_schedule (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    date DATE NOT NULL,
    shift_uuid UUID NOT NULL,
    staff_uuid UUID NOT NULL,
	facility_uuid UUID NOT NULL,
	is_approved BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE salary (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    date DATE NOT NULL,
    duration NUMERIC(5,2),
    day_off INTEGER,
    price NUMERIC(12,2),
    staff_uuid UUID NOT NULL
);

CREATE TABLE plan (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    name VARCHAR(100),
    price INTEGER NOT NULL,
    duration_days INTEGER NOT NULL,
    description TEXT
);

DROP TYPE IF EXISTS status_type CASCADE;

CREATE TYPE status_type AS ENUM (
    'PENDING',
    'SUCCESS',
    'FAILED'
);

CREATE TABLE pay_customer (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    date DATE NOT NULL,
    plan_uuid UUID NOT NULL,
    customer_uuid UUID NOT NULL,
    txn_ref VARCHAR(50),
    bank_code VARCHAR(20),
    status status_type DEFAULT 'PENDING'
);

CREATE TABLE customer_schedule (
    uuid UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
    date DATE NOT NULL,
    checkin TIME NOT NULL,
    checkout TIME NOT NULL,
    facility_uuid UUID NOT NULL,
    staff_uuid UUID NOT NULL,
    customer_uuid UUID NOT NULL,
	note TEXT
);








